from solution import format_amount
import pytest


def test_basic_usd():
    assert format_amount('1234.5', 'USD') == 'USD 1,234.50'


def test_krw_round():
    assert format_amount('1234.5', 'KRW') == 'KRW 1,235'


def test_negative_half_away():
    assert format_amount('-2.5', 'JPY') == 'JPY -3'
    assert format_amount('-1.005', 'USD') == 'USD -1.01'


def test_negative_zero():
    assert format_amount('-0.001', 'USD') == 'USD 0.00'
    assert format_amount('-0.4', 'KRW') == 'KRW 0'
    assert format_amount('-0', 'EUR') == 'EUR 0.00'


def test_bhd():
    assert format_amount('1234567.8905', 'BHD') == 'BHD 1,234,567.891'
    assert format_amount('0.0005', 'KWD') == 'KWD 0.001'


def test_unknown():
    with pytest.raises(ValueError):
        format_amount('1', 'XXX')
    with pytest.raises(ValueError):
        format_amount('1', 'usd')


def test_large():
    assert format_amount('1000000', 'USD') == 'USD 1,000,000.00'
    assert format_amount('999.995', 'USD') == 'USD 1,000.00'


def test_exponent_input():
    assert format_amount('1E+3', 'USD') == 'USD 1,000.00'
    assert format_amount('1E+10', 'USD') == 'USD 10,000,000,000.00'


def test_small_negative_round_to_nonzero():
    assert format_amount('-0.005', 'USD') == 'USD -0.01'


def test_high_precision():
    assert format_amount('12345678901234567890.125', 'USD') == 'USD 12,345,678,901,234,567,890.13'


def test_leading_plus_and_spaces():
    assert format_amount('+5', 'USD') == 'USD 5.00'
